function localToday(): string {
  const now = new Date();
  return new Date(now.getTime() - now.getTimezoneOffset() * 60_000).toISOString().slice(0, 10);
}

function JournalPage() {
  const router = useRouter();
  const queryClient = useQueryClient();
  const routeSearch = Route.useSearch();
  const [learnerChoice, setLearnerChoice] = useState(routeSearch.learner);
  const [periodChoice, setPeriodChoice] = useState(routeSearch.period);
  const [activityPage, setActivityPage] = useState(0);
  // undefined = the default "newest added first" ordering.
  const [activitySort, setActivitySort] = useState<ActivitySort | undefined>(undefined);
  const [addingActivity, setAddingActivity] = useState(false);
  const [isPreparingPdf, setIsPreparingPdf] = useState(false);
  const [learnerSignature, setLearnerSignature] = useState("");
  const [coachSignature, setCoachSignature] = useState("");
  const [learnerSignatureSaved, setLearnerSignatureSaved] = useState(false);
  const [coachSignatureSaved, setCoachSignatureSaved] = useState(false);
  const [isSavingSignatures, setIsSavingSignatures] = useState(false);
  const [signatureError, setSignatureError] = useState("");
  const signaturesSaved = learnerSignatureSaved && coachSignatureSaved;

  const metadata = useQuery({ queryKey: ["journal-metadata"], queryFn: () => getLearners() });
  useEffect(() => {
    if (!metadata.data || learnerChoice) return;
    if (metadata.data.learners[0]) setLearnerChoice(metadata.data.learners[0].id);
  }, [metadata.data, learnerChoice]);

  const selectedLearner = learnerChoice;
  const cumulativeLearner = metadata.data?.learners.find((item) => item.id === selectedLearner);

  // Start / first-evidence / planned-end dates come from the rich learner
  // profile (ILR + evidence sources, plus any auditor-corrected overrides).
  const profile = useQuery({
    queryKey: ["journal-profile", selectedLearner],
    queryFn: () => getLearnerProfile(selectedLearner),
    enabled: Boolean(selectedLearner),
    staleTime: 5 * 60_000,
    retry: 1,
  });
  const delivery = profile.data?.learning_delivery;
  const profileDate = (value?: string | null) => (value ? String(value).slice(0, 10) : "—");

  // The Activity month selector spans the learner's whole programme window:
  // every month from the START DATE up to 2026-08 (the manual-entry cutoff),
  // so any month in range can be opened and filled by hand — merged with any
  // months that already carry activity outside that window (post-cutoff
  // claimed months, "undated", ...).
  const JOURNAL_RANGE_END = "2026-08";
  const learnerPeriods = useMemo(() => {
    const base = cumulativeLearner?.periods ?? [];
    const startKey = delivery?.start_date ? String(delivery.start_date).slice(0, 7) : "";
    if (!/^\d{4}-\d{2}$/.test(startKey)) return base;
    const merged = new Map<string, { value: string; label: string }>();
    let [year, monthNo] = startKey.split("-").map(Number);
    for (let guard = 0; guard < 60; guard += 1) {
      const value = `${String(year).padStart(4, "0")}-${String(monthNo).padStart(2, "0")}`;
      if (value > JOURNAL_RANGE_END) break;
      merged.set(value, {
        value,
        label: new Date(`${value}-02T12:00:00`).toLocaleString("en-GB", { month: "long", year: "numeric" }),
      });
      monthNo += 1;
      if (monthNo > 12) { monthNo = 1; year += 1; }
    }
    for (const period of base) {
      // The journal is a monthly report — the "Undated LMS activities" bucket
      // stays out of it (it remains reachable from the search page).
      if (period.value === "undated") continue;
      merged.set(period.value, period);
    }
    return [...merged.values()].sort((left, right) => left.value.localeCompare(right.value));
  }, [cumulativeLearner, delivery?.start_date]);
  const selectedPeriod = learnerPeriods.some((item) => item.value === periodChoice) ? periodChoice : "";

  useEffect(() => {
    if (!cumulativeLearner) return;
    if (learnerPeriods.some((item) => item.value === periodChoice)) return;
    // Default month = August 2026 (the range end) when available, otherwise
    // the latest month the learner has.
    const fallback = learnerPeriods.some((item) => item.value === JOURNAL_RANGE_END)
      ? JOURNAL_RANGE_END
      : learnerPeriods[learnerPeriods.length - 1]?.value ?? "";
    setPeriodChoice(fallback);
    setActivityPage(0);
    setLearnerSignature("");
    setCoachSignature("");
    setLearnerSignatureSaved(false);
    setCoachSignatureSaved(false);
  }, [cumulativeLearner, learnerPeriods, periodChoice]);

  const monthSummaries = useQuery({
    queryKey: ["journal-summary", selectedLearner, selectedPeriod],
    queryFn: () => getLearners({ period: selectedPeriod, learner: selectedLearner }),
    enabled: Boolean(selectedLearner && selectedPeriod),
  });
  const activities = useQuery({
    queryKey: ["journal-activities", selectedLearner, selectedPeriod, activityPage, activitySort],
    queryFn: () => getLearnerActivities({
      learner: selectedLearner,
      period: selectedPeriod,
      search: "",
      limit: activityPageSize,
      offset: activityPage * activityPageSize,
      sort: activitySort,
    }),
    enabled: Boolean(selectedLearner && selectedPeriod),
    placeholderData: keepPreviousData,
  });
  const savedSignoff = useQuery({
    queryKey: ["journal-signoff", selectedLearner, selectedPeriod],
    queryFn: () => fetchAuditSignoff(selectedLearner, selectedPeriod),
    enabled: Boolean(selectedLearner && selectedPeriod),
    retry: false,
  });

  useEffect(() => {
    if (!savedSignoff.data) return;
    const savedLearnerSignature = savedSignoff.data.signoffs.learner?.signature_data ?? "";
    const savedCoachSignature = savedSignoff.data.signoffs.coach?.signature_data ?? "";
    setLearnerSignature(savedLearnerSignature);
    setCoachSignature(savedCoachSignature);
    setLearnerSignatureSaved(Boolean(savedLearnerSignature));
    setCoachSignatureSaved(Boolean(savedCoachSignature));
    setSignatureError("");
  }, [savedSignoff.data]);

  const learner = monthSummaries.data?.learners.find((item) => item.id === selectedLearner);
  const monthLabel = learnerPeriods.find((item) => item.value === selectedPeriod)?.label ?? "No activity months";
  const activityTotal = activities.data?.total ?? 0;
  const activityTotalPages = Math.max(1, Math.ceil(activityTotal / activityPageSize));
  const activityFrom = activityTotal === 0 ? 0 : activityPage * activityPageSize + 1;
  const activityTo = Math.min((activityPage + 1) * activityPageSize, activityTotal);

  // Pencil edits on the stat cards — same learner_hours_overrides store the
  // search table uses, keyed (learner, selected month). Empty restores the
  // computed value.
  async function editHours(
    field: "planned_hours" | "actual_hours" | "not_accepted_hours",
    label: string,
    current: number | null,
  ) {
    if (!selectedLearner || !selectedPeriod || !learner) return;
    const { value, isConfirmed } = await Swal.fire({
      title: `${label} — ${monthLabel}`,
      text: "Saved for this learner and month. Leave empty to restore the computed value.",
      input: "number",
      inputValue: current == null ? "" : String(Math.round(current * 100) / 100),
      inputAttributes: { min: "0", step: "0.25" },
      showCancelButton: true,
      confirmButtonText: "Save",
    });
    if (!isConfirmed) return;
    const trimmed = String(value ?? "").trim();
    const next = trimmed === "" ? null : Number(trimmed);
    if (next != null && (!Number.isFinite(next) || next < 0 || next > 100000)) {
      return void Swal.fire({ icon: "error", title: "Check the hours", text: "Enter a number between 0 and 100000, or leave the field empty." });
    }
    try {
      await saveLearnerHours({ aptem_id: Number(selectedLearner), period: selectedPeriod, [field]: next });
      await queryClient.invalidateQueries({ queryKey: ["journal-summary"] });
      void Swal.fire({ toast: true, position: "top-end", icon: "success", title: `${label} saved`, showConfirmButton: false, timer: 1600 });
    } catch (cause) {
      await Swal.fire({ icon: "error", title: "Save failed", text: cause instanceof Error ? cause.message : "Could not save the hours." });
    }
  }

  // Pencil edits on the profile dates — stored per learner and applied
  // server-side, so the profile page and the PDF pick the correction up too.
  async function editProfileDate(
    field: "start_date" | "first_evidence_date" | "planned_end_date",
    label: string,
  ) {
    if (!selectedLearner) return;
    const current = delivery?.[field] ? String(delivery[field]).slice(0, 10) : "";
    const { value, isConfirmed } = await Swal.fire({
      title: label,
      text: "Saved for this learner. Leave empty to restore the source date.",
      input: "date",
      inputValue: current,
      showCancelButton: true,
      confirmButtonText: "Save",
    });
    if (!isConfirmed) return;
    try {
      await saveProfileDates({ aptem_id: Number(selectedLearner), [field]: String(value ?? "").trim() || null });
      await queryClient.invalidateQueries({ queryKey: ["journal-profile", selectedLearner] });
      void Swal.fire({ toast: true, position: "top-end", icon: "success", title: `${label} saved`, showConfirmButton: false, timer: 1600 });
    } catch (cause) {
      await Swal.fire({ icon: "error", title: "Save failed", text: cause instanceof Error ? cause.message : "Could not save the date." });
    }
  }

  async function handleDownloadPdf() {
    if (!learner || !selectedLearner || !selectedPeriod) return;
    setIsPreparingPdf(true);
    try {
      const allRows = await getAllJournalActivities(selectedLearner, selectedPeriod);
      await downloadLearnerJournalPdf(learner, monthLabel, allRows, cumulativeLearner, {
        programme: profile.data?.programme ?? cumulativeLearner?.programme,
        coach: profile.data?.coach ?? cumulativeLearner?.coach,
        // Start / first-evidence / planned-end dates on the PDF header.
        learning_delivery: profile.data?.learning_delivery,
      }, {
        learner: learnerSignature,
        coach: coachSignature,
      });
    } finally {
      setIsPreparingPdf(false);
    }
  }

  async function handleSaveSignatures() {
    const aptemId = selectedLearner;
    if (!aptemId || !learner || !learnerSignature || !coachSignature) return;
    setIsSavingSignatures(true);
    setSignatureError("");
    try {
      const now = new Date().toISOString();
      const response = await saveAuditSignoff(aptemId, {
        monthKey: selectedPeriod,
        roles: {
          learner: { signerName: learner.name, signature: learnerSignature, confirmed: true, signedAt: now },
          coach: { signerName: cumulativeLearner?.coach.name ?? "", signature: coachSignature, confirmed: true, signedAt: now },
        },
      });
      queryClient.setQueryData(["journal-signoff", aptemId, selectedPeriod], response);
      setLearnerSignature(response.signoffs.learner?.signature_data ?? learnerSignature);
      setCoachSignature(response.signoffs.coach?.signature_data ?? coachSignature);
      setLearnerSignatureSaved(Boolean(response.signoffs.learner?.signature_data));
      setCoachSignatureSaved(Boolean(response.signoffs.coach?.signature_data));
    } catch (error) {
      setSignatureError(error instanceof Error ? error.message : "Could not save the signatures.");
      setLearnerSignatureSaved(false);
      setCoachSignatureSaved(false);
    } finally {
      setIsSavingSignatures(false);
    }
  }

  async function handleRemoveSignature(role: "learner" | "coach") {
    const aptemId = selectedLearner;
    if (!aptemId || !learner) return;
    const roleLabel = role === "learner" ? "learner" : "coach";
    const confirmation = await Swal.fire({
      icon: "warning",
      title: `Remove ${roleLabel} signature?`,
      text: `This removes the saved ${roleLabel} signature for ${monthLabel}.`,
      showCancelButton: true,
      confirmButtonText: "Yes, remove it",
      cancelButtonText: "Cancel",
      confirmButtonColor: "#b91c1c",
      reverseButtons: true,
    });
    if (!confirmation.isConfirmed) return;
    setIsSavingSignatures(true);
    setSignatureError("");
    try {
      const nextLearnerSignature = role === "learner" ? "" : learnerSignature;
      const nextCoachSignature = role === "coach" ? "" : coachSignature;
      const now = new Date().toISOString();
      const response = await saveAuditSignoff(aptemId, {
        monthKey: selectedPeriod,
        roles: {
          learner: { signerName: learner.name, signature: nextLearnerSignature, confirmed: Boolean(nextLearnerSignature), signedAt: nextLearnerSignature ? now : "" },
          coach: { signerName: cumulativeLearner?.coach.name ?? "", signature: nextCoachSignature, confirmed: Boolean(nextCoachSignature), signedAt: nextCoachSignature ? now : "" },
        },
      });
      queryClient.setQueryData(["journal-signoff", aptemId, selectedPeriod], response);
      setLearnerSignature(response.signoffs.learner?.signature_data ?? "");
      setCoachSignature(response.signoffs.coach?.signature_data ?? "");
      setLearnerSignatureSaved(Boolean(response.signoffs.learner?.signature_data));
      setCoachSignatureSaved(Boolean(response.signoffs.coach?.signature_data));
      await Swal.fire({ icon: "success", title: "Signature removed", text: `The ${roleLabel} signature was removed successfully.`, timer: 1800, showConfirmButton: false });
    } catch (error) {
      const message = error instanceof Error ? error.message : "Could not remove the signature.";
      setSignatureError(message);
      await Swal.fire({ icon: "error", title: "Could not remove signature", text: message });
    } finally {
      setIsSavingSignatures(false);
    }
  }
  const isLoading =
    metadata.isLoading ||
    (Boolean(selectedPeriod) && monthSummaries.isLoading) ||
    (Boolean(selectedLearner && selectedPeriod) && activities.isLoading);
  // Rich profile/sign-off data is optional for newly added programmes. Core
  // cohort/month/activity failures still block the journal; optional 404s do not.
  const pageError = metadata.error || monthSummaries.error || activities.error;

  return (
    <div className="min-h-screen bg-background">
      <header className="border-b border-border bg-surface">
        <div className="flex w-full flex-wrap items-center justify-between gap-4 px-6 py-4">
          <div className="flex items-baseline gap-3">
            <span className="font-serif text-base text-foreground">OTJ&nbsp;Ledger</span>
            <span className="label-caps">Live learner journal</span>
          </div>
          <div className="flex items-center gap-4 text-xs text-muted-foreground">
            <button type="button" onClick={() => router.history.back()} className="font-medium text-foreground hover:underline">← Back</button>
            <Link to="/search" className="font-medium hover:underline">Search</Link>
            <Link to="/activity" search={{ learner: selectedLearner }} className="font-medium hover:underline">Activity log</Link>
          </div>
        </div>
      </header>

      <main className="mx-auto w-full max-w-[1700px] space-y-6 px-6 py-8">
        <section className="overflow-hidden rounded-xl border border-border bg-card shadow-panel">
          <div className="h-1 bg-[#182d48]" />
          <div className="flex flex-wrap items-center justify-between gap-6 px-7 py-6">
            <div className="flex items-center gap-5">
              <img src="/assets/kbc-logo.png" alt="Kent Business College" className="h-16 w-36 object-contain object-left" />
              <span className="h-14 w-px bg-border" />
              <div>
                <h1 className="text-2xl font-semibold tracking-tight text-[#182d48]">Learner Journal</h1>
              </div>
            </div>
            <div className="flex items-center gap-3">
              <div className="rounded-xl bg-[#f6f8fb] px-6 py-3 text-center">
                <p className="text-[9px] font-semibold uppercase tracking-[0.12em] text-muted-foreground">Reporting month</p>
                <p className="mt-1 text-sm font-semibold text-[#182d48]">{metadata.isLoading ? "Loading…" : monthLabel}</p>
              </div>
              <Button
                className="gap-2 bg-[#182d48] hover:bg-[#243f61]"
                disabled={!learner || !activities.data || !signaturesSaved || isPreparingPdf}
                onClick={handleDownloadPdf}
              >
                {isPreparingPdf ? <LoaderCircle className="h-4 w-4 animate-spin" /> : <Download className="h-4 w-4" />}
                {isPreparingPdf ? "Preparing PDF..." : "Download PDF"}
              </Button>
            </div>
          </div>

          <div className="grid gap-4 border-y border-border bg-[#fafbfc] px-7 py-5 sm:grid-cols-2">
            <label><span className="label-caps">Learner</span><select className="mt-1.5 h-9 w-full rounded-md border border-border bg-card px-3 text-sm" value={selectedLearner} onChange={(event) => { setLearnerChoice(event.target.value); setPeriodChoice(""); setActivityPage(0); setLearnerSignature(""); setCoachSignature(""); setLearnerSignatureSaved(false); setCoachSignatureSaved(false); }}>{metadata.data?.learners.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label>
            <label><span className="label-caps">Activity month</span><select className="mt-1.5 h-9 w-full rounded-md border border-border bg-card px-3 text-sm disabled:cursor-not-allowed disabled:opacity-60" value={selectedPeriod} disabled={!learnerPeriods.length} onChange={(event) => { setPeriodChoice(event.target.value); setActivityPage(0); setLearnerSignature(""); setCoachSignature(""); setLearnerSignatureSaved(false); setCoachSignatureSaved(false); }}>{learnerPeriods.length ? learnerPeriods.map((item) => <option key={item.value} value={item.value}>{item.label}</option>) : <option value="">No activity months available</option>}</select></label>
          </div>

          {pageError ? (
            <p className="py-10 text-center text-sm text-destructive">
              {pageError instanceof Error ? pageError.message : "Could not load the journal."}
            </p>
          ) : selectedLearner && !learnerPeriods.length ? (
            <p className="py-10 text-center text-sm text-muted-foreground">No activity months are available for this learner.</p>
          ) : isLoading || !selectedLearner || !selectedPeriod ? (
            <p className="py-10 text-center text-sm text-muted-foreground">Loading journal…</p>
          ) : learner ? (
            <div className="space-y-5 px-7 py-6">
              <div className="grid rounded-lg bg-[#f6f8fb] px-5 lg:grid-cols-3">
                <ProfileGroup label="Learner" value={learner.name} secondaryLabel="Start date" secondaryValue={profileDate(delivery?.start_date)} onEditSecondary={() => void editProfileDate("start_date", "Start date")} />
                <ProfileGroup label="Programme" value={cumulativeLearner?.programme ?? "—"} secondaryLabel="First evidence" secondaryValue={profileDate(delivery?.first_evidence_date)} onEditSecondary={() => void editProfileDate("first_evidence_date", "First evidence")} />
                <ProfileGroup label="Coach" value={cumulativeLearner?.coach.name ?? "—"} secondaryLabel="Planned end" secondaryValue={profileDate(delivery?.planned_end_date)} onEditSecondary={() => void editProfileDate("planned_end_date", "Planned end")} />
              </div>
              <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
                {/* Hour overrides entered from the Learner search table flow into
                    these stats — the hint keeps their provenance visible in the
                    signed journal. */}
                {/* Planned hours come from the ILR (or a manual override), not
                    from the LMS hours-mapping pipeline — show them even while
                    Claimed/Variance still wait for mapped actuals. */}
                <Stat label="Monthly plan" value={learner.planned_hours_available === false ? "—" : `${learner.planned_hours.toFixed(2)} h`} hint={learner.planned_hours_overridden ? "Manually entered" : undefined} onEdit={() => void editHours("planned_hours", "Monthly plan", learner.planned_hours_available === false ? null : learner.planned_hours)} />
                <Stat label="Claimed" value={learner.hours_mapped === false ? "—" : `${learner.actual_hours.toFixed(2)} h`} tone="purple" hint={learner.actual_hours_overridden ? "Manually entered" : undefined} onEdit={() => void editHours("actual_hours", "Claimed", learner.hours_mapped === false ? null : learner.actual_hours)} />
                <Stat label="Not accepted" value={learner.not_accepted_overridden ? `${(learner.not_accepted_hours ?? 0).toFixed(2)} h` : learner.hours_mapped === false ? "—" : `${(learner.not_accepted_hours ?? 0).toFixed(2)} h`} tone="warning" hint={learner.not_accepted_overridden ? "Manually entered" : undefined} onEdit={() => void editHours("not_accepted_hours", "Not accepted", learner.not_accepted_hours ?? null)} />
                <Stat label="Variance" value={learner.hours_mapped === false ? "—" : `${learner.gap_hours > 0 ? "+" : ""}${learner.gap_hours.toFixed(2)} h`} tone={learner.gap_hours < 0 ? "warning" : "success"} hint={learner.planned_hours_overridden || learner.actual_hours_overridden ? "From manual entry" : undefined} />
              </div>
              {(learner.planned_hours_overridden || learner.actual_hours_overridden) && (
                <p className="text-xs text-muted-foreground">
                  * Manually entered hours replace the computed totals above; the OTJH breakdown below still reflects the source mirror values.
                </p>
              )}
              <OtjhCard otjh={activities.data?.otjh} />
            </div>
          ) : null}
        </section>

        <section className="overflow-hidden rounded-xl border border-border bg-card shadow-panel">
          <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-7 py-5">
            <div>
              <h2 className="text-lg font-semibold text-[#182d48]">Activity log</h2>
              <p className="mt-1 text-sm text-muted-foreground">Claimed and accepted off-the-job learning time</p>
            </div>
            <div className="flex items-center gap-2">
              <span className="rounded-full bg-[#f6f8fb] px-3 py-1.5 font-mono text-xs font-medium text-[#182d48]">{activities.data?.total ?? 0} activities</span>
              <Button
                size="sm"
                disabled={!selectedLearner || !learner || addingActivity}
                onClick={() => setAddingActivity(true)}
                title={!selectedLearner ? "Choose a learner first" : undefined}
              ><Plus className="h-3.5 w-3.5" /> Add activity</Button>
            </div>
          </header>
          <div className="overflow-x-auto">
            <Table>
              <TableHeader>
                <ActivityTableHeader
                  dark
                  sort={activitySort}
                  onSort={(key) => {
                    setActivitySort((current) => nextActivitySort(current, key));
                    setActivityPage(0);
                  }}
                />
              </TableHeader>
              <TableBody>
                {addingActivity && selectedLearner && learner ? (
                  <InlineActivityCreateRow
                    learnerId={Number(selectedLearner)}
                    learnerName={learner.name}
                    onCancel={() => setAddingActivity(false)}
                    // New rows must land in the month being viewed, or the
                    // month filter hides them the moment they are saved.
                    defaultDate={selectedPeriod && !localToday().startsWith(selectedPeriod) ? `${selectedPeriod}-01` : localToday()}
                  />
                ) : null}
                {activities.data?.items.map((row, index, rows) => {
                  // Week headers only make sense while rows run in date order
                  // (they group consecutive rows); other sort orders interleave
                  // weeks and would spray duplicate headers.
                  const weekHeaders = activitySort?.key === "date" && activitySort.dir === "asc";
                  // A week header appears when the label differs from the last
                  // NON-NULL label — week-less mirror rows interleaved between
                  // plan rows must not retrigger the same header.
                  const lastWeek = rows.slice(0, index).reduce<string | null>(
                    (value, item) => item.week ?? value,
                    null,
                  );
                  return (
                    <Fragment key={row.id}>
                    {weekHeaders && row.week && row.week !== lastWeek ? (
                      <TableRow className="border-y border-[#cbd5e1] bg-[#eef3f8] hover:bg-[#eef3f8]">
                        <TableCell colSpan={10} className="pl-7 text-xs font-semibold uppercase tracking-wider text-[#182d48]">
                          {row.week}
                        </TableCell>
                      </TableRow>
                    ) : null}
                    <InlineActivityRow row={row} className="odd:bg-[#f7f9fc]" />
                    </Fragment>
                  );
                })}
              </TableBody>
            </Table>
          </div>
          <footer className="flex flex-wrap items-center justify-between gap-3 border-t border-border px-7 py-4">
            <p className="text-xs text-muted-foreground">
              Showing <span className="font-mono font-medium text-foreground">{activityFrom}–{activityTo}</span> of <span className="font-mono font-medium text-foreground">{activityTotal}</span> activities
            </p>
            <div className="flex items-center gap-2">
              <Button variant="outline" size="sm" disabled={activityPage === 0 || activities.isFetching} onClick={() => setActivityPage((page) => Math.max(0, page - 1))}>
                <ArrowLeft className="h-3.5 w-3.5" /> Previous
              </Button>
              <span className="min-w-24 text-center text-xs text-muted-foreground">
                Page <span className="font-mono font-medium text-foreground">{activityPage + 1}</span> of <span className="font-mono font-medium text-foreground">{activityTotalPages}</span>
              </span>
              <Button variant="outline" size="sm" disabled={activityPage + 1 >= activityTotalPages || activities.isFetching} onClick={() => setActivityPage((page) => Math.min(activityTotalPages - 1, page + 1))}>
                Next <ArrowRight className="h-3.5 w-3.5" />
              </Button>
            </div>
          </footer>
        </section>

        <section className="rounded-xl border border-border bg-card p-7 shadow-panel">
          <div className="mb-5 flex flex-wrap items-start justify-between gap-4">
            <div>
              <h2 className="text-lg font-semibold text-[#182d48]">Report sign-off</h2>
              <p className="mt-1 text-sm text-muted-foreground">Saved for this learner and month, then embedded in every downloaded PDF.</p>
              {signatureError && <p className="mt-2 text-xs text-destructive">{signatureError}</p>}
            </div>
            <div className="flex items-center gap-2">
              <Button
                type="button"
                disabled={!learnerSignature || !coachSignature || isSavingSignatures || signaturesSaved}
                onClick={handleSaveSignatures}
                className="min-w-36 bg-[#182d48] hover:bg-[#243f61]"
              >
                {isSavingSignatures ? <LoaderCircle className="h-4 w-4 animate-spin" /> : signaturesSaved ? <CheckCircle2 className="h-4 w-4" /> : <Save className="h-4 w-4" />}
                {isSavingSignatures ? "Saving..." : signaturesSaved ? "Saved" : "Save signatures"}
              </Button>
            </div>
          </div>
          <div className="grid gap-4 lg:grid-cols-2">
            <SignatureCapture label="Learner signature" signer={learner?.name ?? ""} value={learnerSignature} onChange={(value) => { setLearnerSignature(value); setLearnerSignatureSaved(false); }} onRemove={() => handleRemoveSignature("learner")} canRemove={learnerSignatureSaved} isRemoving={isSavingSignatures} />
            <SignatureCapture label="Coach signature" signer={cumulativeLearner?.coach.name ?? ""} value={coachSignature} onChange={(value) => { setCoachSignature(value); setCoachSignatureSaved(false); }} onRemove={() => handleRemoveSignature("coach")} canRemove={coachSignatureSaved} isRemoving={isSavingSignatures} />
          </div>
        </section>
      </main>
    </div>
  );
}
